def xor_net(x1, x2):
    h1 = fires([2, 2], [x1, x2], -1)
    h2 = fires([-2, -2], [x1, x2], 3)
    return fires([2, 2], [h1, h2], -3)

widget.prelude:
def weighted_sum(weights, inputs, bias):
    total = bias
    for i in range(len(weights)):
        total = total + weights[i] * inputs[i]
    return total

def fires(weights, inputs, bias):
    if weighted_sum(weights, inputs, bias) > 0:
        return 1
    return 0
